package dev.colonyhorizons.mayor;
import dev.colonyhorizons.remote.*;
import dev.colonyhorizons.remote.RemoteModels.*;
import dev.colonyhorizons.supply.*;
import com.ldtteam.structurize.storage.StructurePacks;
import com.ldtteam.structurize.placement.*;
import com.minecolonies.api.colony.IColonyManager;
import com.minecolonies.api.util.LoadOnlyStructureHandler;
import net.minecraft.server.level.*;
import net.minecraft.core.BlockPos;
import java.util.*;

/** Upgrades only original huts inside their already-reviewed maximum envelopes. */
public final class MayorUpgrades {
 private MayorUpgrades(){}
 private static Development owned(ServerPlayer actor,UUID id){var r=RemoteDevelopmentData.get(actor.serverLevel()).find(id).orElseThrow();var colony=IColonyManager.getInstance().getColonyByDimension(r.draft().request().colonyId(),actor.level().dimension());if(colony==null||!actor.getUUID().equals(r.owner())||!r.owner().equals(colony.getPermissions().getOwner()))throw new SecurityException("Only the current owner can review upgrades");return r;}
 public static MayorProposals.Entry review(ServerPlayer actor,UUID id,UUID building){
  var level=actor.serverLevel();var r=owned(actor,id);if(r.phase()!=Phase.OPERATING||!MayorService.available(level,id)||!MayorLogistics.ready(level,id)||!RemoteTickets.snapshot(level).containsKey(id))throw new IllegalArgumentException("Complete the settlement and local logistics first");
  var plan=RemoteDevelopmentData.get(level).buildings(r.id()).stream().filter(p->p.operationId().equals(building)).findFirst().orElseThrow(()->new IllegalArgumentException("Unknown local hut"));var colony=IColonyManager.getInstance().getColonyByDimension(r.draft().request().colonyId(),level.dimension());var nativeBuilding=colony.getServerBuildingManager().getBuilding(plan.anchor());if(nativeBuilding==null||!nativeBuilding.isBuilt()||!FoundingPlacement.isPaidAnchor(level,plan))throw new IllegalArgumentException("Original completed hut is unavailable");int from=nativeBuilding.getBuildingLevel();if(from>=r.draft().request().maxBuildingLevel())throw new IllegalArgumentException("Building has reached your approved level cap");
  var path=plan.blueprint().replace("1.blueprint",(from+1)+".blueprint");validate(level,r,plan,from,path);var cost=bill(level,plan,path);var ledger=MayorProposals.get(level);var result=ledger.propose(id,r.owner(),building,from,path,plan.hash(),cost);ledger.checkpoint(level);return result;
 }
 public static void decide(ServerPlayer actor,UUID id,UUID proposal,long revision,boolean approve){var r=owned(actor,id);if(r.phase()!=Phase.OPERATING||!MayorService.available(actor.serverLevel(),id))throw new IllegalArgumentException("Resume the operating outpost before deciding");var ledger=MayorProposals.get(actor.serverLevel());var entry=ledger.entries().get(proposal);if(entry==null||!entry.settlement().equals(id))throw new IllegalArgumentException("Unknown outpost proposal");if(approve)validateApproved(actor.serverLevel(),r,entry);ledger.decide(actor.getUUID(),proposal,revision,approve);ledger.checkpoint(actor.serverLevel());}
 public static void validateApproved(ServerLevel level,Development r,MayorProposals.Entry entry){var plan=RemoteDevelopmentData.get(level).buildings(r.id()).stream().filter(p->p.operationId().equals(entry.building())).findFirst().orElseThrow();if(!entry.settlement().equals(r.id())||!entry.owner().equals(r.owner())||!entry.hash().equals(plan.hash())||entry.target()>r.draft().request().maxBuildingLevel())throw new IllegalArgumentException("Upgrade exceeds the reviewed plan");validate(level,r,plan,entry.from(),entry.blueprint());if(!bill(level,plan,entry.blueprint()).equals(entry.cost()))throw new IllegalArgumentException("Upgrade materials changed; review before building");}
 private static void validate(ServerLevel level,Development r,BuildingPlan plan,int from,String path){
  FoundingPlacement.validatePack(level,r);if(!FoundingPlacement.isPaidAnchor(level,plan)||from<1||from>=r.draft().request().maxBuildingLevel()||!path.equals(plan.blueprint().replace("1.blueprint",(from+1)+".blueprint")))throw new IllegalArgumentException("Unapproved upgrade");
  var colony=IColonyManager.getInstance().getColonyByDimension(r.draft().request().colonyId(),level.dimension());var b=colony.getServerBuildingManager().getBuilding(plan.anchor());if(b==null||!b.isBuilt()||b.getBuildingLevel()!=from)throw new IllegalArgumentException("Hut changed since review");RemoteConstruction.validateNativeRequirements(b);var builderPlan=RemoteDevelopmentData.get(level).buildings(r.id()).stream().filter(p->p.role().equals("builder")).findFirst().orElseThrow();var builder=colony.getServerBuildingManager().getBuilding(builderPlan.anchor());if(builder==null||!builder.isBuilt()||!plan.role().equals("builder")&&builder.getBuildingLevel()<from+1)throw new IllegalArgumentException("Upgrade the local builder first");
  var current=StructurePacks.getBlueprint(plan.pack(),plan.blueprint().replace("1.blueprint",from+".blueprint"),level.registryAccess());var target=StructurePacks.getBlueprint(plan.pack(),path,level.registryAccess());var origin=plan.anchor().subtract(current.getPrimaryBlockOffset());var targetOrigin=plan.anchor().subtract(target.getPrimaryBlockOffset());var area=plan.upgradeVolume();
  for(int x=0;x<target.getSizeX();x++)for(int z=0;z<target.getSizeZ();z++){var floor=targetOrigin.offset(x,-1,z);if(!level.hasChunkAt(floor)||!level.getFluidState(floor).isEmpty()||!level.getBlockState(floor).isFaceSturdy(level,floor,net.minecraft.core.Direction.UP))throw new IllegalArgumentException("Restore the supporting ground before upgrading");}

  for(var pos:BlockPos.betweenClosed(targetOrigin,targetOrigin.offset(target.getSizeX()-1,target.getSizeY()-1,target.getSizeZ()-1))){var chunk=new net.minecraft.world.level.ChunkPos(pos);var claim=IColonyManager.getInstance().getClaimData(level.dimension(),chunk);if(!area.isInside(pos)||!level.hasChunkAt(pos)||!level.getWorldBorder().isWithinBounds(pos)||claim==null||claim.getOwningColony()!=colony.getID()||!RemoteDevelopmentData.get(level).confirmedClaims(r.id()).contains(chunk))throw new IllegalArgumentException("Upgrade land is unavailable");if(pos.equals(plan.anchor()))continue;var relative=pos.subtract(origin);boolean inside=relative.getX()>=0&&relative.getY()>=0&&relative.getZ()>=0&&relative.getX()<current.getSizeX()&&relative.getY()<current.getSizeY()&&relative.getZ()<current.getSizeZ();var actual=level.getBlockState(pos);var expected=inside?current.getBlockState(relative):net.minecraft.world.level.block.Blocks.AIR.defaultBlockState();if(actual.getBlock()!=expected.getBlock()&&!actual.isAir()&&!actual.canBeReplaced())throw new IllegalArgumentException("Preserve changed building blocks; restore the original design before upgrading");if(!level.getFluidState(pos).isEmpty())throw new IllegalArgumentException("Clear the liquid hazard before upgrading");}
 }
 public static Map<ItemKey,Integer> bill(ServerLevel level,BuildingPlan plan,String path){var bp=StructurePacks.getBlueprint(plan.pack(),path,level.registryAccess());var placer=new StructurePlacer(new LoadOnlyStructureHandler(level,plan.anchor(),bp,plan.transform()));var cursor=AbstractBlueprintIterator.NULL_POS;var result=new HashMap<ItemKey,Integer>();for(int guard=0;;guard++){if(guard>=10000)throw new IllegalArgumentException("Upgrade review is too large");var step=placer.executeStructureStep(level,null,cursor,StructurePlacer.Operation.GET_RES_REQUIREMENTS,()->placer.getIterator().increment((info,pos,handler)->false),true);for(var item:step.getBlockResult().getRequiredItems())if(!item.isEmpty()&&!(item.getItem() instanceof net.minecraft.world.item.BlockItem block&&block.getBlock() instanceof com.minecolonies.api.blocks.AbstractBlockHut<?>))result.merge(new ItemKey(item),item.getCount(),Math::addExact);cursor=step.getIteratorPos();if(step.getBlockResult().getResult()==BlockPlacementResult.Result.FINISHED)break;}return Map.copyOf(result);}
 private static boolean affordable(ServerLevel level,Development r,MayorProposals.Entry entry){var hut=(com.minecolonies.core.tileentities.TileEntityColonyBuilding)level.getBlockEntity(r.draft().request().homeSupply());if(hut==null)return false;var stock=new HashMap<ItemKey,Integer>();var inventory=WarehouseInventory.resolve(level,hut).inventory();for(int i=0;i<inventory.getSlots();i++){var stack=inventory.getStackInSlot(i);if(!stack.isEmpty())stock.merge(new ItemKey(stack),stack.getCount(),Math::addExact);}var actual=MayorReservations.get(level);var trial=MayorReservations.load(actual.save(level.registryAccess()),level.registryAccess());var founding=FoundingCargo.load(RemoteDevelopmentData.get(level).foundingCargo(r.id()).orElseThrow(),level.registryAccess());return entry.cost().isEmpty()||trial.reserve(r.owner(),r.id(),r.draft().request().homeSupply(),entry.id(),r.draft().request().budget(),founding.items(),stock,entry.cost());}
 public static StepResult tick(ServerLevel level,UUID id){var data=RemoteDevelopmentData.get(level);var r=data.find(id).orElseThrow();if(r.phase()!=Phase.OPERATING)return idle();var actor=level.getServer().getPlayerList().getPlayer(r.owner());if(actor==null||!MayorService.available(level,id)||!MayorLogistics.ready(level,id))return idle();var ledger=MayorProposals.get(level);
  for(var entry:ledger.entries().values())if(entry.settlement().equals(id)&&entry.state()==MayorProposals.State.APPROVED){var done=data.construction(id).values().stream().anyMatch(e->e.building().equals(entry.building())&&e.target()==entry.target()&&e.state()==ConstructionJournal.State.COMPLETE);if(done){ledger.complete(entry.id());ledger.checkpoint(level);return new StepResult("Upgrade complete",List.of(),true);}try{validateApproved(level,r,entry);if(!affordable(level,r,entry))return new StepResult("Upgrade needs supplies",List.of("Keep Home reserves and provide the approved upgrade materials"),false);return RemoteConstruction.queueUpgrade(level,id,entry.id());}catch(IllegalArgumentException e){return new StepResult("Upgrade needs review",List.of(e.getMessage()),false);}}
  var pending=ledger.entries().values().stream().filter(e->e.settlement().equals(id)&&e.state()==MayorProposals.State.PROPOSED).findFirst();
  if(pending.isPresent()){if(r.mode()==Mode.APPROVAL)return new StepResult("Upgrade needs your approval",List.of(),false);var entry=pending.orElseThrow();try{if(!affordable(level,r,entry))return new StepResult("Upgrade needs supplies",List.of("Respecting the approved allowance and Home reserve"),false);decide(actor,id,entry.id(),entry.revision(),true);return new StepResult("Upgrade approved within your limits",List.of(),true);}catch(IllegalArgumentException e){return new StepResult("Upgrade needs review",List.of(e.getMessage()),false);}}
  var colony=IColonyManager.getInstance().getColonyByDimension(r.draft().request().colonyId(),level.dimension());var candidates=new ArrayList<>(RemoteDevelopmentData.get(level).buildings(r.id()));candidates.removeIf(p->colony.getServerBuildingManager().getBuilding(p.anchor())==null);candidates.sort(Comparator.<BuildingPlan>comparingInt(p->colony.getServerBuildingManager().getBuilding(p.anchor()).getBuildingLevel()).thenComparingInt(p->p.role().equals("builder")?0:1));
  for(var plan:candidates){var b=colony.getServerBuildingManager().getBuilding(plan.anchor());if(b==null||b.getBuildingLevel()>=r.draft().request().maxBuildingLevel()||ledger.entries().values().stream().anyMatch(e->e.settlement().equals(id)&&e.building().equals(plan.operationId())&&e.from()==b.getBuildingLevel()))continue;try{review(actor,id,plan.operationId());return new StepResult("Upgrade review prepared",List.of(),true);}catch(IllegalArgumentException ignored){/* Native prerequisites or changed terrain leave the building alone. */}}
  return idle();
 }
 private static StepResult idle(){return new StepResult("No approved upgrade waiting",List.of(),false);}
}
